(() => {
'use strict';
const preview=Boolean(window.DTT_FORCE_PREVIEW)||location.protocol==='file:'||new URLSearchParams(location.search).get('preview')==='1';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',chart:'M4 20V4 M4 20h17 M8 16v-4 M13 16V7 M18 16v-7',phone:'M8 3H4a1 1 0 0 0-1 1c0 9.4 7.6 17 17 17a1 1 0 0 0 1-1v-4l-5-2-2 2a14 14 0 0 1-6-6l2-2-2-5z',clock:'M12 8v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.9 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1 1-3z',upload:'M12 16V3 M7 8l5-5 5 5 M4 15v5h16v-5',download:'M12 3v13 M7 11l5 5 5-5 M4 17v4h16v-4',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',chevron:'M9 5l7 7-7 7',left:'M15 5l-7 7 7 7',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',refresh:'M20 7v5h-5 M4 17v-5h5 M6 6a8 8 0 0 1 13 1l1 5 M18 18a8 8 0 0 1-13-1l-1-5',target:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0 M13 12h-2',bolt:'M13 2 4 14h7l-1 8 10-13h-7l1-7z',info:'M12 11v6 M12 7v.1 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',check:'M5 12l4 4L19 6',close:'M6 6l12 12 M18 6 6 18',file:'M14 2H5v20h14V7l-5-5z M14 2v6h5 M8 12h8 M8 16h8',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',edit:'M14 5l5 5 M4 20l5-1L21 7l-5-5L4 14v6z',calendar:'M8 2v4 M16 2v4 M3 10h18 M3 4h18v17H3z',shield:'M12 2l9 4v6c0 5-5 9-9 10-4-1-9-5-9-10V6l9-4z M8 12l3 3 5-6',print:'M7 8V3h10v5 M7 17H3V8h18v9h-4 M7 14h10v7H7z M17 11h.1',menu:'M4 6h16 M4 12h16 M4 18h16',logout:'M9 3H3v18h6 M10 12h11 M16 7l5 5-5 5',sort:'M8 4v16 M4 16l4 4 4-4 M16 20V4 M12 8l4-4 4 4',external:'M14 3h7v7 M21 3l-11 11 M10 3H3v18h18v-7'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`;
const num=(n,d=0)=>Number(n||0).toLocaleString('en-CA',{maximumFractionDigits:d,minimumFractionDigits:d});
const pct=n=>`${num(n,0)}%`;
const initials=n=>String(n||'?').trim().split(/\s+/).slice(0,2).map(v=>v[0]).join('').toUpperCase();
const colors=['#a694d8','#86b8c7','#cf9f85','#91ba94','#ad9acb','#c794a4'];
const avatar=(name,i=0)=>`<span class="avatar" style="background:${colors[i%colors.length]}20;color:${colors[i%colors.length]}">${esc(initials(name))}</span>`;
const fmtDate=(s,opts={month:'short',day:'numeric'})=>{try{return new Intl.DateTimeFormat('en-CA',{...opts,timeZone:'UTC'}).format(new Date(s+'T12:00:00Z'))}catch{return s}};
const duration=s=>s==null?'—':`${Math.floor(s/60)}:${String(Math.round(s%60)).padStart(2,'0')}`;
const dateNow=()=>{try{return new Intl.DateTimeFormat('en-CA',{timeZone:state.bootstrap?.settings.timezone||'America/Costa_Rica',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}catch{return new Date().toISOString().slice(0,10)}};
const dateAdd=(s,n)=>{const d=new Date(s+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
const nav=[['overview','grid','Overview'],['matrix','chart','DTT matrix'],['calls','phone','Call activity'],['manual','clock','Manual time'],['team','users','Team members'],['integration','link','Outreach connection'],['settings','settings','Workspace settings']];
const state={dataset:'demo',page:'overview',bootstrap:null,report:null,start:'',end:'',team:'all',search:'',period:'week',callsPage:1,sort:'dtt',busy:false,error:null,lastFetched:null,callState:'all'};
let modalReturn=null,searchTimer,refreshTimer,requestId=0;
function toast(message,error=false){$('#toast-root').innerHTML=`<div class="toast${error?' error':''}">${esc(message)}</div>`;setTimeout(()=>{$('#toast-root').innerHTML=''},5500)}
async function api(path,options={}){if(preview)return window.DTTPulsePreview.request(path,options);let response;try{response=await fetch(path,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}})}catch{throw Error('The app cannot reach the server. Check your connection and try again.')}if(response.status===401){showLogin();throw Object.assign(Error('Sign in to access your workspace.'),{unauthorized:true})}const type=response.headers.get('content-type')||'';const value=type.includes('json')?await response.json():await response.text();if(!response.ok)throw Object.assign(Error(value.error||(value.errors?.length?'The import contains validation errors.':'The request could not be completed.')),{details:value,status:response.status});return value}
const payload=(method,body)=>({method,body:JSON.stringify(body)});
const params=()=>new URLSearchParams({dataset:state.dataset,start:state.start,end:state.end,team:state.team,search:state.search});
async function load(initial=false,quiet=false){const current=++requestId,requestedDataset=state.dataset;if(!quiet)state.busy=true;try{if(initial||!state.bootstrap||quiet){const bootstrap=await api('/api/bootstrap?dataset='+requestedDataset);if(current!==requestId)return;state.bootstrap=bootstrap;state.start=state.start||state.bootstrap.range.start;state.end=state.end||state.bootstrap.range.end}const report=await api('/api/report?'+params());if(current!==requestId)return;state.report=report;state.error=null;state.lastFetched=new Date();state.busy=false;render()}catch(error){if(current!==requestId)return;state.busy=false;state.error=error.message;if(error.unauthorized){if(!state.bootstrap)$('#app').innerHTML='<div class="boot"><span class="brand-mark">p</span><h2>DTT Pulse</h2><p>Sign in to open your workspace.</p></div>';return}if(state.bootstrap)render();else $('#app').innerHTML=`<div class="boot">${icon('link')}<h2>Workspace unavailable</h2><p>${esc(error.message)}</p><button class="button primary" id="retry-boot">Try again</button></div>`;$('#retry-boot')?.addEventListener('click',()=>load(true))}}
function filters(){return `<div class="filterbar"><div class="filter-left"><label class="screen-reader" for="period">Reporting period</label><select class="control" id="period"><option value="today" ${state.period==='today'?'selected':''}>Today</option><option value="week" ${state.period==='week'?'selected':''}>This week</option><option value="lastweek" ${state.period==='lastweek'?'selected':''}>Last week</option><option value="month" ${state.period==='month'?'selected':''}>This month</option><option value="custom" ${state.period==='custom'?'selected':''}>Custom dates</option></select><div class="filter-date"><label class="screen-reader" for="date-start">Start date</label><input class="control" type="date" id="date-start" value="${esc(state.start)}"><span>–</span><label class="screen-reader" for="date-end">End date</label><input class="control" type="date" id="date-end" value="${esc(state.end)}"></div><label class="screen-reader" for="team-filter">Team</label><select class="control" id="team-filter"><option value="all">All teams</option>${state.bootstrap.teams.map(t=>`<option ${state.team===t?'selected':''} value="${esc(t)}">${esc(t)}</option>`).join('')}</select></div><div class="filter-right"><div class="search-box">${icon('search')}<label class="screen-reader" for="search">Search agents or calls</label><input id="search" placeholder="Search agents or calls…" value="${esc(state.search)}"></div><button class="icon-button" id="clear-filters" title="Reset filters" aria-label="Reset filters">${icon('refresh')}</button></div></div>`}
function render(){if(!state.bootstrap)return;const b=state.bootstrap,r=state.report;const current=nav.find(n=>n[0]===state.page)||nav[0];const dataPage=['overview','matrix','calls','manual'].includes(state.page);const descriptions={overview:'A clear view of your team’s calls, time, and daily progress.',matrix:'See every agent’s DTT by day, with consistent reporting rules.',calls:'Explore the call records behind your team’s activity.',manual:'Keep meetings and offline contributions in the same report.',team:'Manage the people and team assignments in this workspace.',integration:'Connect Outreach to keep your team’s activity up to date.',settings:'Define how your workspace calculates and reports DTT.'};
const syncedAt=r?.lastSync||b.integration.lastSync;const sync=state.error?'Refresh failed':state.dataset==='demo'?(preview?'Standalone preview':'Sample workspace'):syncedAt?'Last sync '+new Date(syncedAt).toLocaleTimeString('en-CA',{hour:'2-digit',minute:'2-digit'}):'No Outreach sync yet';
$('#app').innerHTML=`${state.busy?'<div class="loading-strip"></div>':''}<div class="app-shell"><aside class="sidebar" id="sidebar"><a class="brand" href="#overview" aria-label="DTT Pulse home"><span class="brand-mark">p</span><span class="brand-name">DTT <span>Pulse</span></span></a><div class="workspace"><div class="workspace-icon">CA</div><div><strong>Canada AM workspace</strong><small>TEAM PERFORMANCE</small></div></div><p class="nav-label">WORKSPACE</p><nav class="nav-list" aria-label="Main navigation">${nav.slice(0,5).map(([id,ic,label])=>`<button class="nav-button ${state.page===id?'active':''}" data-nav="${id}" ${state.page===id?'aria-current="page"':''} title="${label}">${icon(ic)}<span>${label}</span>${id==='team'?`<span class="nav-count">${b.agents.length}</span>`:''}</button>`).join('')}</nav><p class="nav-label nav-separator">MANAGE</p><nav class="nav-list" aria-label="Manage workspace">${nav.slice(5).map(([id,ic,label])=>`<button class="nav-button ${state.page===id?'active':''}" data-nav="${id}" ${state.page===id?'aria-current="page"':''} title="${label}">${icon(ic)}<span>${label}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="connection-mini"><strong><span class="dot ${b.integration.connected?'green':'orange'}"></span>Outreach ${b.integration.connected?'connected':'not connected'}</strong><p>${b.integration.connected?'Your server is connected. Review sync health for the latest status.':'Bring your call activity into one shared workspace.'}</p><button data-nav="integration">${b.integration.connected?'View connection':'Set up connection'} ${icon('arrow')}</button></div><div class="profile"><span class="avatar" style="background:#ff785e20;color:var(--coral)">CA</span><div><strong>Canada workspace</strong><small>${b.auth.role==='viewer'?'Viewer':'Workspace admin'}${preview?' · Preview':''}</small></div></div></div></aside><main class="main"><header class="topbar"><button class="icon-button mobile-menu" id="mobile-menu" aria-label="Open menu">${icon('menu')}</button><div class="breadcrumb"><span class="crumb-home">Workspace</span><span class="crumb-home">/</span><span>${current[2]}</span></div><div class="top-actions"><span class="status-line"><span class="dot ${state.error?'orange':state.dataset==='demo'?'orange':b.integration.connected?'green':''}"></span>${esc(sync)}</span>${state.dataset==='demo'?'<span class="pill demo">SAMPLE DATA'+(preview?' · PREVIEW':'')+'</span>':'<span class="pill neutral">LIVE WORKSPACE</span>'}<div class="data-mode"><label class="screen-reader" for="dataset">Data workspace</label><select id="dataset" class="control" ${preview?'disabled title="Live data requires the full app"':''}><option value="demo" ${state.dataset==='demo'?'selected':''}>Sample data</option><option value="live" ${state.dataset==='live'?'selected':''}>Live data</option></select></div><button class="icon-button" id="print" aria-label="Print current report" title="Print / save PDF">${icon('print')}</button>${b.auth.required?`<button class="icon-button" id="logout" aria-label="Sign out" title="Sign out">${icon('logout')}</button>`:''}</div></header><div class="content"><div class="page-heading"><div><p class="eyebrow">${state.page==='overview'?'EVERY CONVERSATION COUNTS':'DTT PULSE / '+current[2]}</p><h1>${state.page==='overview'?'Your team, in focus.':current[2]}</h1><p class="page-subtitle">${descriptions[state.page]}</p></div><div class="heading-actions">${dataPage?`<button class="button" data-action="export">${icon('download')}Export report</button><button class="button primary" data-action="${state.page==='manual'?'add-manual':'import'}">${icon(state.page==='manual'?'plus':'upload')}${state.page==='manual'?'Log time':'Import calls'}</button>`:''}${state.page==='team'?`<button class="button" data-nav="integration">${icon('link')}Manage data connection</button><button class="button primary" data-action="add-agent" ${b.auth.role==='viewer'?'disabled':''}>${icon('plus')}Add team member</button>`:''}</div></div>${dataPage?filters():''}${state.error?`<div class="notice error">${icon('info')}<span><strong>Data may be out of date.</strong> ${esc(state.error)}</span><button class="button small" id="retry">Retry</button></div>`:''}${state.dataset==='live'&&dataPage&&b.integration.lastError?`<div class="notice warning">${icon('info')}<span><strong>Outreach synchronization needs attention.</strong> ${esc(b.integration.lastError)}</span><button class="button small" data-nav="integration">Review connection</button></div>`:state.dataset==='live'&&state.page==='overview'&&!b.integration.connected?`<div class="notice">${icon('link')}<span><strong>Your live workspace is ready.</strong> Import a CSV to begin, or connect Outreach for automatic updates.</span><button class="button small" data-nav="integration">Connect Outreach</button></div>`:''}${r&&dataPage&&r.summary.unverified?`<div class="notice warning">${icon('info')}<span><strong>${num(r.summary.unverified)} calls need duration verification.</strong> DTT totals are partial. Eligible dial credits are counted; unverified call duration is excluded.</span><button class="button small" data-nav="settings">Review rules</button></div>`:''}<div id="page-content">${r?view():`<div class="empty">${icon('refresh')}<p>Loading report…</p></div>`}</div><footer class="footer-note"><span>${icon('shield')}${state.dataset==='demo'?'Illustrative sample data. Separate from your live workspace.':'Shared reporting · '+esc(b.settings.timezone)}</span><span>DTT Pulse <span aria-hidden="true">·</span> ${esc(b.settings.timezone)} <span aria-hidden="true">·</span> ${num(b.settings.dailyTarget)} min daily target / agent</span></footer></div></main></div>`;
bind();}
function stat(label,value,unit,foot,ic,featured=false){return `<article class="stat-card ${featured?'featured':''}"><div class="stat-top"><span>${label}</span><span class="stat-symbol">${icon(ic)}</span></div><div class="stat-value mono">${value}<small>${unit}</small></div><div class="stat-foot">${foot}</div></article>`}
function overview(){const s=state.report.summary;return `<section class="stats-grid" aria-label="Team metrics">${stat(s.isComplete===false||s.unverified?'Partial DTT':'Total DTT',num(s.totalDtt,0),'min',`${icon('bolt')} Call time + dial credits + manual time`,'bolt',true)}${stat('Total dials',num(s.dials),'calls',`${num(s.activeAgents)} active agents <span class="faint">/ ${num(s.rosterAgents)} on roster</span>`,'phone')}${stat('Call duration',num(s.callMinutes,0),'min',`${num(s.provisional)} calls in progress · excluded from totals`,'clock')}${stat('Target attainment',pct(s.attainment),'',`${num(s.totalDtt,0)} <span class="faint">of ${num(s.target)} target minutes</span>`,'target')}</section><section class="grid-activity"><article class="panel"><div class="panel-heading"><div><h2>Activity over time</h2><p>Your team’s DTT, broken down by contribution</p></div><span class="pill neutral">${state.report.dates.length===1?'Daily view':state.report.dates.length+' days'}</span></div><div class="chart-legend"><span class="legend-item"><i class="legend-dot" style="background:var(--coral)"></i>Call duration</span><span class="legend-item"><i class="legend-dot" style="background:var(--blue)"></i>Dial credits</span><span class="legend-item"><i class="legend-dot" style="background:var(--violet)"></i>Manual time</span><span class="legend-item"><i class="legend-dot" style="background:var(--faint)"></i>Daily target</span></div><div class="chart-wrap">${activityChart()}</div><div class="chart-foot"><span>${esc(fmtDate(state.start))} – ${esc(fmtDate(state.end,{month:'short',day:'numeric',year:'numeric'}))}</span><strong>${num(s.dialCredits,0)} min from dial credits</strong></div></article>${composition()}</section><section class="panel leaderboard"><div class="panel-heading"><div><h2>Team leaderboard</h2><p>Progress toward each agent’s reporting-period target</p></div><button class="button small subtle" data-nav="matrix">View DTT matrix ${icon('arrow')}</button></div>${agentTable(true)}<div class="table-footer"><span>${state.report.agents.length} agents <span aria-hidden="true">·</span> Ranked by total DTT</span><button class="button small subtle" data-action="add-manual">${icon('plus')}Log manual time</button></div></section>`}
function activityChart(){let days=state.report.daily;if(days.length>31){const grouped=[];for(let i=0;i<days.length;i+=Math.ceil(days.length/20)){const part=days.slice(i,i+Math.ceil(days.length/20));grouped.push(part.reduce((a,d)=>({...a,callMinutes:a.callMinutes+d.callMinutes,dialCredits:a.dialCredits+d.dialCredits,manualMinutes:a.manualMinutes+d.manualMinutes,totalDtt:a.totalDtt+d.totalDtt,target:a.target+d.target}),{date:part[0].date,end:part.at(-1).date,callMinutes:0,dialCredits:0,manualMinutes:0,totalDtt:0,target:0}))}days=grouped}if(!days.length)return empty('No activity in this range','Choose another reporting period.','calendar');const w=700,h=220,top=20,bottom=183,left=47,right=15,plot=w-left-right,maxRaw=Math.max(...days.map(d=>Math.max(d.totalDtt,d.target)),1),step=Math.pow(10,Math.floor(Math.log10(maxRaw)))/2,max=Math.ceil(maxRaw/step)*step,scale=(bottom-top)/max,slot=plot/days.length,bw=Math.min(47,slot*.55);let svg=`<svg class="activity-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="Stacked DTT minutes by date: call duration, dial credits, and manual time. Dashed gray lines show daily targets.">`;
for(let i=0;i<=4;i++){const y=bottom-(bottom-top)*i/4;svg+=`<line class="axis" x1="${left}" y1="${y}" x2="${w-right}" y2="${y}"/><text x="${left-10}" y="${y+3}" text-anchor="end">${num(max*i/4)}</text>`}days.forEach((d,i)=>{const x=left+slot*i+slot/2-bw/2;let y=bottom;svg+=`<g class="activity-bar"><title>${esc(fmtDate(d.date))}${d.end?' – '+esc(fmtDate(d.end)):''}: ${num(d.totalDtt,1)} DTT minutes. ${num(d.callMinutes,1)} call minutes, ${num(d.dialCredits,1)} dial credits, ${num(d.manualMinutes,1)} manual minutes. Target ${num(d.target)} minutes.</title>`;for(const[key,color]of[['callMinutes','#ff785e'],['dialCredits','#7b9eff'],['manualMinutes','#a992f2']]){const hh=d[key]*scale;y-=hh;svg+=`<rect x="${x}" y="${y}" width="${bw}" height="${Math.max(0,hh)}" fill="${color}" rx="1.7"/>`}const ty=bottom-d.target*scale;svg+=`<line x1="${x-7}" y1="${ty}" x2="${x+bw+7}" y2="${ty}" stroke="#9aa5b8" stroke-width="1.5" stroke-dasharray="3 3"/></g>`;if(days.length<16||i%2===0)svg+=`<text class="day-label" x="${x+bw/2}" y="205" text-anchor="middle">${esc(days.length<=7?fmtDate(d.date,{weekday:'short'}):fmtDate(d.date))}</text>`});return svg+'</svg>'}
function composition(){const s=state.report.summary,total=s.totalDtt||1,parts=[['Call duration',s.callMinutes,'#ff785e'],['Dial credits',s.dialCredits,'#7b9eff'],['Manual time',s.manualMinutes,'#a992f2']],circ=2*Math.PI*51;let offset=0;const rings=parts.map(([,v,c])=>{const length=v/total*circ;const result=`<circle cx="70" cy="70" r="51" fill="none" stroke="${c}" stroke-width="12" stroke-dasharray="${Math.max(0,length-2)} ${circ}" stroke-dashoffset="${-offset}"/>`;offset+=length;return result}).join('');return `<article class="panel composition"><h2>Where the time goes</h2><p>Every minute, accounted for.</p><div class="ring-layout"><svg viewBox="0 0 140 140" class="ring-chart" aria-hidden="true"><circle cx="70" cy="70" r="51" fill="none" stroke="#2b3340" stroke-width="12"/>${rings}</svg><div class="ring-center"><strong class="mono">${num(s.totalDtt)}</strong><small>DTT MINUTES</small></div></div>${parts.map(([label,v,c])=>`<div class="composition-row"><span class="composition-label"><i class="legend-dot" style="background:${c}"></i>${label}</span><span class="mono">${num(v,0)} <span class="faint">min</span></span></div>`).join('')}<div class="formula-note">DTT = verified call duration + ${num(state.bootstrap.settings.dialCredit,2).replace(/\.00$/,'')} min per eligible dial + manual time.</div></article>`}
function agentTable(short=false){const agents=state.report.agents.slice(0,short?6:undefined);if(!agents.length)return empty('No agents match these filters','Try a different team or search term.','users');return `<div class="table-wrap"><table><thead><tr><th>Agent</th><th>Team</th><th class="numeric">Dials</th><th class="numeric">Call time</th><th class="numeric">Manual</th><th class="numeric">Total DTT</th><th>Target progress</th></tr></thead><tbody>${agents.map((a,i)=>`<tr><td><div class="rep-cell"><span class="rank ${i===0?'top':''}">${String(i+1).padStart(2,'0')}</span>${avatar(a.name,i)}<div><span class="rep-name">${esc(a.name)}</span></div></div></td><td class="team-cell">${esc(a.team||'Unassigned')}</td><td class="numeric">${num(a.dials)}</td><td class="numeric">${num(a.callMinutes,1)} <span class="faint">m</span></td><td class="numeric">${a.manualMinutes?num(a.manualMinutes)+' <span class="faint">m</span>':'<span class="faint">—</span>'}</td><td class="numeric"><strong>${num(a.totalDtt,1)}</strong> <span class="faint">m</span></td><td class="progress-cell"><div class="progress-line"><div class="progress-track"><div class="progress-fill ${a.attainment>=100?'success':''}" style="width:${Math.min(100,Math.max(0,a.attainment))}%"></div></div><span>${pct(a.attainment)}</span></div></td></tr>`).join('')}</tbody></table></div>`}
function matrix(){const r=state.report,s=state.bootstrap.settings;return `<section class="panel page-panel"><div class="panel-heading"><div><h2>Daily DTT matrix</h2><p>Minutes per agent · ${num(s.dailyTarget)} min daily target · weekdays only</p></div><span class="pill neutral">${r.agents.length} agents</span></div><div class="table-wrap"><table class="matrix"><thead><tr><th>Agent / team</th>${r.dates.map(d=>`<th>${esc(fmtDate(d,{weekday:'short'}))}<br><span class="faint">${esc(fmtDate(d))}</span></th>`).join('')}<th>Total DTT</th><th>Attainment</th></tr></thead><tbody>${r.agents.map((a,i)=>`<tr><td><div class="rep-cell">${avatar(a.name,i)}<div><span class="rep-name">${esc(a.name)}</span><small>${esc(a.team||'Unassigned')}</small></div></div></td>${r.dates.map(d=>{const v=a.daily[d]||0;return `<td><span class="heat-cell ${v>=s.dailyTarget?'high':v>=s.dailyTarget*.5?'mid':v?'low':''}" title="${esc(a.name)} · ${esc(d)} · ${num(v,2)} DTT minutes">${v?num(v,1):'—'}</span></td>`}).join('')}<td class="mono"><strong>${num(a.totalDtt,1)}</strong></td><td class="mono ${a.attainment>=100?'green':''}">${pct(a.attainment)}</td></tr>`).join('')}</tbody></table></div>${!r.agents.length?empty('No matching agents','Adjust the filters to see your team.','users'):''}<div class="table-footer"><span>Totals retain full precision. Displayed minutes are rounded.</span><span class="green">Green = daily target met</span></div></section>`}
function callStatus(c){const pending=['ringing','in_progress','in-progress','initiated'].includes(c.state),final=['completed','complete'].includes(c.state);return `<span class="state-chip ${pending?'pending':final?'final':'other'}"><i class="dot"></i>${esc(String(c.state||'Unknown').replaceAll('_',' ').replace(/^./,v=>v.toUpperCase()))}</span>`}
function calls(){const r=state.report;const filtered=r.calls.filter(c=>state.callState==='all'||(state.callState==='pending'?['ringing','in_progress','in-progress','initiated'].includes(c.state):state.callState==='unverified'?!c.durationVerified:c.state===state.callState));const per=20,pages=Math.max(1,Math.ceil(filtered.length/per));state.callsPage=Math.min(state.callsPage,pages);const rows=filtered.slice((state.callsPage-1)*per,state.callsPage*per);return `<section class="panel page-panel"><div class="panel-heading"><div><h2>Call activity</h2><p>Open a call to see its source, details, and calculation notes.</p></div><label class="screen-reader" for="call-state">Call state</label><select class="control" id="call-state"><option value="all">All call states</option><option value="completed" ${state.callState==='completed'?'selected':''}>Completed</option><option value="no_answer" ${state.callState==='no_answer'?'selected':''}>No answer</option><option value="pending" ${state.callState==='pending'?'selected':''}>In progress</option><option value="unverified" ${state.callState==='unverified'?'selected':''}>Duration unverified</option></select></div><div class="summary-strip"><div><small>Records in range</small><strong>${num(r.calls.length)}</strong></div><div><small>Eligible dials</small><strong>${num(r.summary.dials)}</strong></div><div><small>Provisional calls</small><strong>${num(r.summary.provisional)}</strong></div><div><small>Duration unverified</small><strong>${num(r.summary.unverified)}</strong></div></div><div class="table-wrap"><table><thead><tr><th>Agent</th><th>Date / time</th><th>State</th><th class="numeric">Duration</th><th>Disposition</th><th>Source</th><th></th></tr></thead><tbody>${rows.map((c,i)=>`<tr><td><div class="rep-cell">${avatar(c.rep,i)}<span class="rep-name">${esc(c.rep)}</span></div></td><td class="nowrap">${esc(fmtDate(c.date))}<small class="faint" style="display:block">${esc(formatTime(c.createdAt))}</small></td><td>${callStatus(c)}</td><td class="numeric ${c.durationVerified?'':'faint'}">${c.durationVerified?duration(c.durationSec):'Unverified'}</td><td><div class="calls-note" title="${esc(c.disposition)}">${esc(c.disposition||'—')}</div></td><td><span class="pill ${c.source==='demo'?'demo':'neutral'}">${esc(c.source==='demo'?'Sample':c.source==='outreach'?'Outreach':'CSV')}</span></td><td><button class="icon-button" data-call="${esc(c.id)}" aria-label="View call by ${esc(c.rep)}">${icon('chevron')}</button></td></tr>`).join('')}</tbody></table></div>${rows.length?'':empty('No matching calls','Change the reporting period or import a call file.','phone')}<div class="table-footer"><span>${filtered.length?num((state.callsPage-1)*per+1):0}–${num(Math.min(state.callsPage*per,filtered.length))} of ${num(filtered.length)} calls</span><div class="pagination"><button id="previous-calls" ${state.callsPage===1?'disabled':''} aria-label="Previous calls">${icon('left')}</button><span>Page ${state.callsPage} / ${pages}</span><button id="next-calls" ${state.callsPage===pages?'disabled':''} aria-label="Next calls">${icon('chevron')}</button></div></div></section><div class="notice">${icon('info')}<span><strong>Call duration is different from a connected conversation.</strong> DTT uses verified duration data. In-progress calls are excluded from finalized totals.</span></div>`}
function formatTime(v){if(!v)return'—';try{return new Intl.DateTimeFormat('en-CA',{hour:'2-digit',minute:'2-digit',timeZone:state.bootstrap.settings.timezone}).format(new Date(v))}catch{return'—'}}
function manual(){const rows=[...state.report.manual].sort((a,b)=>b.date.localeCompare(a.date));return `<section class="stats-grid" style="grid-template-columns:repeat(3,minmax(0,1fr))">${stat('Manual time',num(state.report.summary.manualMinutes),'min','Included in total DTT','clock',true)}${stat('Time entries',num(rows.length),'entries','Within the selected reporting period','calendar')}${stat('Contributing agents',num(new Set(rows.map(m=>m.userId)).size),'agents','Meetings and other eligible time','users')}</section><section class="panel page-panel"><div class="panel-heading"><div><h2>Manual time log</h2><p>Each entry adds minutes to one agent on a specific reporting date.</p></div><button class="button small" data-action="add-manual">${icon('plus')}Log time</button></div><div class="table-wrap"><table><thead><tr><th>Agent</th><th>Date</th><th>Activity</th><th class="numeric">Minutes</th><th>Notes</th><th></th></tr></thead><tbody>${rows.map((m,i)=>`<tr><td><div class="rep-cell">${avatar(m.rep,i)}<span class="rep-name">${esc(m.rep)}</span></div></td><td class="nowrap">${esc(fmtDate(m.date))}</td><td><span class="pill neutral">${esc(m.source)}</span></td><td class="numeric">${num(m.minutes,1)}</td><td><div class="calls-note" title="${esc(m.note)}">${esc(m.note||'—')}</div></td><td><button class="icon-button" data-delete-manual="${esc(m.id)}" aria-label="Delete ${num(m.minutes)} minute entry for ${esc(m.rep)}" ${state.bootstrap.auth.role==='viewer'?'disabled':''}>${icon('trash')}</button></td></tr>`).join('')}</tbody></table></div>${rows.length?'':empty('Make every contribution visible','Log time spent in merchant meetings or other eligible activities.','clock')}<div class="table-footer"><span>${rows.length} entries <span aria-hidden="true">·</span> ${num(state.report.summary.manualMinutes,1)} total minutes</span><span>Recorded separately from Outreach calls</span></div></section>`}
function team(){const aa=state.bootstrap.agents;return `<div class="notice">${icon('info')}<span>Team assignments control reporting filters. Disabling an agent removes them from active roster targets; their stored records are retained.</span></div><section class="panel page-panel"><div class="panel-heading"><div><h2>Workspace roster</h2><p>${aa.filter(a=>a.active).length} active agents across ${state.bootstrap.teams.length} teams</p></div><span class="pill neutral">${state.dataset==='demo'?'Sample roster':'Shared roster'}</span></div><div class="table-wrap"><table><thead><tr><th>Agent</th><th>Team</th><th>Identity</th><th>Status</th><th></th></tr></thead><tbody>${aa.map((a,i)=>`<tr><td><div class="rep-cell">${avatar(a.name,i)}<span class="rep-name">${esc(a.name)}</span></div></td><td>${esc(a.team||'Unassigned')}</td><td class="faint">${String(a.id).startsWith('name:')?'CSV name match':String(a.id).startsWith('demo')?'Sample ID':'User ID'} <span class="mono">${esc(a.id)}</span></td><td><span class="pill ${a.active?'success':'neutral'}">${a.active?'Active':'Inactive'}</span></td><td><button class="button small subtle" data-edit-agent="${esc(a.id)}" ${state.bootstrap.auth.role==='viewer'?'disabled':''}>${icon('edit')}Edit</button></td></tr>`).join('')}</tbody></table></div>${aa.length?'':empty('Your roster will appear here','Add a team member for manual time, import calls, or connect Outreach to build your roster.','users')}</section>`}
function integration(){const s=state.bootstrap.integration;return `<div class="integration-grid"><section class="panel integration-hero"><span class="pill integration-status ${s.connected?'success':'warning'}">${s.connected?'Connected':preview?'Preview only':'Not connected'}</span><div class="integration-logo">o</div><h2>Your calls. Automatically.</h2><p>Connect your Outreach workspace to bring call activity into DTT Pulse. Scheduled checks and call-change notifications keep shared reports current.</p><div class="integration-actions">${s.connected?`<button class="button primary" data-action="sync">${icon('refresh')}Sync now</button><button class="button" data-action="webhooks">${icon('bolt')}Enable notifications</button><button class="button danger" data-action="disconnect">Disconnect</button>`:`<button class="button primary" data-action="connect">${icon('link')}Connect Outreach</button><button class="button" data-action="setup">View setup requirements ${icon('arrow')}</button>`}</div><div class="integration-details"><div><small>Connection method</small><strong>Secure OAuth authorization</strong></div><div><small>Refresh target</small><strong>Approximately every 60 seconds</strong></div><div><small>Access scope</small><strong>Configured agent allowlist</strong></div><div><small>Data destination</small><strong>Live workspace only</strong></div></div></section><section class="panel setup-steps"><h2>Connection checklist</h2>${[[s.configured,'Configure server access','Set up your Outreach OAuth app, credentials, callback URL, encryption key, and allowed agent IDs.'],[s.connected,'Authorize your workspace','Sign in with an Outreach account that can read the required team’s calls.'],[s.durationVerified,'Verify the duration mapping','Compare a recent CSV export with API results before including API call duration in DTT.'],[Boolean(s.lastSync),'Validate the first sync','Compare agents, dials, dates, and DTT with your existing report.']].map(([done,title,copy],i)=>`<div class="setup-step"><span class="step-num ${done?'done':''}">${done?'✓':i+1}</span><div><strong>${title}</strong><p>${copy}</p></div></div>`).join('')}</section><section class="panel integration-wide"><div class="panel-heading"><div><h2>Synchronization health</h2><p>Live connection status. Sample data never simulates an Outreach sync.</p></div><button class="button small subtle" id="refresh-integration">${icon('refresh')}Refresh status</button></div><div class="sync-health"><div><small>Last successful sync</small><strong>${s.lastSync?esc(new Date(s.lastSync).toLocaleString()):'No successful sync yet'}</strong></div><div><small>Pending events</small><strong>${num(s.pendingEvents)}</strong></div><div><small>API duration</small><strong class="${s.durationVerified?'green':'coral'}">${s.durationVerified?'Mapping configured':'Awaiting verification'}</strong></div></div>${s.lastError?`<div class="notice error" style="margin:0 20px 20px">${icon('info')}<span>${esc(s.lastError)}</span></div>`:''}</section><div class="notice integration-wide">${icon('shield')}<span>Outreach credentials are handled by the server. Your browser receives reporting data and connection status. ${preview?'This standalone preview cannot connect to Outreach.':'Configure access in the server environment before authorizing.'}</span></div></div>`}
function settings(){const s=state.bootstrap.settings;return `<div class="settings-layout"><form class="panel padded" id="settings-form"><h2>Calculation & reporting</h2><p>These rules apply to ${state.dataset==='demo'?'the sample':'your live'} workspace. Values recalculate across reports.</p><div class="form-grid"><div class="field full"><label for="timezone">Reporting timezone</label><select id="timezone" name="timezone">${[...new Set([s.timezone,'America/Costa_Rica','America/Toronto','America/Vancouver','America/Halifax','America/St_Johns','America/Edmonton','America/Winnipeg','UTC'])].map(t=>`<option value="${esc(t)}" ${t===s.timezone?'selected':''}>${esc(t.replaceAll('_',' '))}</option>`).join('')}</select><small>Controls reporting dates and target cutoffs. CSV dates without a timezone keep their written date.</small></div><div class="field"><label for="daily-target">Daily target per agent</label><input id="daily-target" name="dailyTarget" type="number" value="${s.dailyTarget}" min="1" max="1440" step="0.5" required><small>Minutes per weekday. Future days add no target.</small></div><div class="field"><label for="dial-credit">Credit per eligible dial</label><input id="dial-credit" name="dialCredit" type="number" value="${s.dialCredit}" min="0" max="60" step="0.25" required><small>Added separately from verified call duration.</small></div><div class="field full"><label for="directions">Eligible call directions</label><select id="directions" name="directions"><option value="both" ${s.directions.length===2?'selected':''}>Inbound and outbound</option><option value="outbound" ${s.directions.length===1&&s.directions[0]==='outbound'?'selected':''}>Outbound only</option><option value="inbound" ${s.directions.length===1&&s.directions[0]==='inbound'?'selected':''}>Inbound only</option></select></div><div class="field full"><label for="duration-mode">Outreach duration mapping</label><select id="duration-mode" name="durationMode"><option value="unverified" ${s.durationMode==='unverified'?'selected':''}>Unverified — exclude API call duration</option><option value="field" ${s.durationMode==='field'?'selected':''}>Verified API duration field (seconds)</option><option value="answered_to_completed" ${s.durationMode==='answered_to_completed'?'selected':''}>Verified answered-to-completed time</option></select><small>Only change after comparing API results with the official CSV. Choosing a mapping is an explicit confirmation that it matches your reporting rule.</small></div><div class="field full" id="duration-field-row" ${s.durationMode!=='field'?'hidden':''}><label for="duration-field">API duration field name</label><input id="duration-field" name="durationField" value="${esc(s.durationField||'duration')}" pattern="[A-Za-z][A-Za-z0-9_]*"><small>The selected field must contain the validated duration in seconds.</small></div><div class="field full"><label for="eligible-states">Eligible finalized call states</label><input id="eligible-states" name="eligibleStates" value="${esc(s.eligibleStates.join(', '))}" required><small>Comma-separated state values. Ringing and in-progress calls stay provisional.</small></div><label class="checkbox-field field full"><span><input name="includeManualCalls" type="checkbox" ${s.includeManualCalls?'checked':''}> Include manually logged Outreach calls</span><small>This applies to call records. Manual meeting time is tracked separately.</small></label></div><div class="form-actions"><span class="tagline">${state.dataset==='demo'?'Changes affect sample data only.':'Applies to all authorized workspace viewers.'}</span><button class="button primary" type="submit" ${state.bootstrap.auth.role==='viewer'?'disabled':''}>Save settings</button></div></form><aside class="panel settings-note"><h3>How DTT is calculated</h3><div class="explain-row"><strong>1. Verified call duration</strong><p>Sum eligible call durations in seconds, then divide by 60. CSV “Duration in Seconds” is authoritative.</p></div><div class="explain-row"><strong>2. Dial credits</strong><p>Each unique, eligible finalized call adds the configured minute credit. Repeated imports update records by call ID.</p></div><div class="explain-row"><strong>3. Manual contributions</strong><p>Meeting entries add minutes to the selected agent and reporting date.</p></div><div class="explain-row"><strong>4. A consistent target</strong><p>Daily target × active roster agents × elapsed weekdays in the range, including today.</p></div><div class="explain-row"><strong>Keep precision</strong><p>Totals use full precision. Display rounding never changes stored records.</p></div></aside></div>`}
function empty(title,message,ic='grid'){return `<div class="empty">${icon(ic)}<strong>${title}</strong><p>${message}</p></div>`}
function view(){return({overview,matrix,calls,manual,team,integration,settings}[state.page]||overview)()}
function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.nav)));$('.brand')?.addEventListener('click',e=>{e.preventDefault();navigate('overview')});document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>action(b.dataset.action)));$('#mobile-menu')?.addEventListener('click',()=>{$('#sidebar').classList.toggle('open')});$('#print')?.addEventListener('click',()=>window.print());$('#logout')?.addEventListener('click',async()=>{try{await api('/api/logout',payload('POST',{}));showLogin()}catch(e){toast(e.message,true)}});$('#dataset')?.addEventListener('change',async e=>{state.dataset=e.target.value;state.bootstrap=null;state.report=null;state.team='all';state.search='';state.callsPage=1;await load(true)});$('#period')?.addEventListener('change',e=>{state.period=e.target.value;setPeriod(state.period);state.callsPage=1;load()});for(const id of['date-start','date-end'])$('#'+id)?.addEventListener('change',()=>{const a=$('#date-start').value,b=$('#date-end').value;if(!a||!b)return;if(a>b){toast('The start date must be on or before the end date.',true);return}if((new Date(b)-new Date(a))/86400000>365){toast('Choose a reporting range of 366 days or fewer.',true);return}state.start=a;state.end=b;state.period='custom';state.callsPage=1;load()});$('#team-filter')?.addEventListener('change',e=>{state.team=e.target.value;state.callsPage=1;load()});$('#search')?.addEventListener('input',e=>{state.search=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{const at=$('#search')?.selectionStart;state.callsPage=1;await load();$('#search')?.focus();$('#search')?.setSelectionRange(at,at)},350)});$('#clear-filters')?.addEventListener('click',()=>{state.search='';state.team='all';state.period='week';setPeriod('week');load()});$('#retry')?.addEventListener('click',()=>load(true));$('#call-state')?.addEventListener('change',e=>{state.callState=e.target.value;state.callsPage=1;render()});$('#previous-calls')?.addEventListener('click',()=>{state.callsPage--;render()});$('#next-calls')?.addEventListener('click',()=>{state.callsPage++;render()});document.querySelectorAll('[data-call]').forEach(b=>b.addEventListener('click',()=>callModal(b.dataset.call)));document.querySelectorAll('[data-edit-agent]').forEach(b=>b.addEventListener('click',()=>agentModal(b.dataset.editAgent)));document.querySelectorAll('[data-delete-manual]').forEach(b=>b.addEventListener('click',()=>deleteManual(b.dataset.deleteManual)));$('#settings-form')?.addEventListener('submit',saveSettings);$('#duration-mode')?.addEventListener('change',e=>{$('#duration-field-row').hidden=e.target.value!=='field'});$('#refresh-integration')?.addEventListener('click',refreshIntegration)}
function setPeriod(period){const today=dateNow(),dow=(new Date(today+'T12:00Z').getUTCDay()+6)%7;if(period==='today')state.start=state.end=today;else if(period==='week'){state.start=dateAdd(today,-dow);state.end=today}else if(period==='lastweek'){state.start=dateAdd(today,-dow-7);state.end=dateAdd(today,-dow-1)}else if(period==='month'){state.start=today.slice(0,7)+'-01';state.end=today}}
function navigate(page){state.page=page;state.callsPage=1;try{history.replaceState(null,'','#'+page)}catch{}render();window.scrollTo({top:0,behavior:'instant'});if(page==='integration')refreshIntegration(true)}
async function refreshIntegration(quiet=false){try{state.bootstrap.integration=await api('/api/outreach/status');if(state.page==='integration')render();if(!quiet)toast('Connection status updated.')}catch(e){if(!quiet)toast(e.message,true)}}
async function action(name){if(['connect','sync','webhooks','disconnect'].includes(name)&&state.bootstrap.auth.role==='viewer')return toast('An administrator manages the Outreach connection.',true);if(name==='import')return importModal();if(name==='add-manual')return manualModal();if(name==='add-agent')return agentModal(null);if(name==='export')return exportReport();if(name==='setup')return setupModal();if(name==='connect'){if(preview||!state.bootstrap.integration.configured)return setupModal();location.href='/api/outreach/connect';return}if(name==='disconnect'){return confirmModal('Disconnect Outreach?','This stops future synchronization. Stored call records remain available for reporting.','Disconnect',async()=>{const result=await api('/api/outreach/disconnect',payload('POST',{}));await refreshIntegration(true);toast(result.message||(result.grantRevocationRequired?'Local credentials removed. Revoke the app authorization in Outreach to finish disconnecting.':'Outreach disconnected.'),Boolean(result.remainingWebhooks))})}try{if(name==='sync'){const result=await api('/api/outreach/sync',payload('POST',{}));toast(result.status==='queued'?'Synchronization queued. Check connection status for completion.':'Synchronization requested.');await refreshIntegration(true)}else if(name==='webhooks'){await api('/api/outreach/webhooks',payload('POST',{}));toast('Call-change notifications registered.');await refreshIntegration(true)}}catch(e){toast(e.message,true)}}
function openModal(title,subtitle,body,wide=false){modalReturn=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop" id="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><div class="modal-head"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button class="icon-button" id="close-modal" aria-label="Close dialog">${icon('close')}</button></div>${body}</section></div>`;document.body.style.overflow='hidden';$('#close-modal').addEventListener('click',closeModal);$('#modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal()});$('#modal-root').querySelector('.modal').focus();$('#modal-root').addEventListener('keydown',modalKeys);$('#cancel-modal')?.addEventListener('click',closeModal)}
function modalKeys(e){if(e.key==='Escape')closeModal();if(e.key!=='Tab')return;const focusable=[...$('#modal-root').querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled&&!el.hidden&&el.offsetParent!==null);if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement.classList.contains('modal'))){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
function closeModal(){$('#modal-root').innerHTML='';$('#modal-root').removeEventListener('keydown',modalKeys);document.body.style.overflow='';modalReturn?.isConnected&&modalReturn.focus()}
function confirmModal(title,message,label,onConfirm){openModal(title,message,`<div class="form-actions"><button class="button" id="cancel-modal">Cancel</button><button class="button danger" id="confirm-action">${label}</button></div>`);$('#confirm-action').addEventListener('click',async e=>{e.target.disabled=true;try{await onConfirm();closeModal()}catch(error){e.target.disabled=false;toast(error.message,true)}})}
function manualModal(){if(state.bootstrap.auth.role==='viewer')return toast('An administrator can add manual time.',true);const agents=state.bootstrap.agents.filter(a=>a.active);if(!agents.length)return toast('Add a team member on the Team members page, import calls, or connect Outreach first.',true);openModal('Log manual time','Add a meeting or other eligible activity to an agent’s DTT.',`<form id="manual-form"><div class="form-grid"><div class="field full"><label for="manual-agent">Agent</label><select id="manual-agent" name="userId" required><option value="">Select an agent</option>${agents.map(a=>`<option value="${esc(a.id)}">${esc(a.name)} · ${esc(a.team||'Unassigned')}</option>`).join('')}</select></div><div class="field"><label for="manual-date">Reporting date</label><input type="date" id="manual-date" name="date" value="${dateNow()}" required></div><div class="field"><label for="manual-minutes">Minutes</label><input type="number" id="manual-minutes" name="minutes" min="0.5" max="1440" step="0.5" placeholder="e.g. 30" required></div><div class="field full"><label for="manual-source">Activity type</label><select id="manual-source" name="source"><option>Zoom</option><option>Google Meet</option><option>Other</option></select></div><div class="field full"><label for="manual-note">Notes <span class="faint">(optional)</span></label><textarea id="manual-note" name="note" maxlength="2000" placeholder="Briefly describe the activity"></textarea></div></div><div class="form-actions"><span class="tagline">${state.dataset==='demo'?'Sample workspace only':'Shared with your workspace'}</span><button class="button" type="button" id="cancel-modal">Cancel</button><button class="button primary" type="submit">Add time</button></div></form>`);$('#manual-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),button=e.target.querySelector('[type=submit]');button.disabled=true;try{await api('/api/manual',payload('POST',{dataset:state.dataset,userId:f.get('userId'),date:f.get('date'),minutes:Number(f.get('minutes')),source:f.get('source'),note:f.get('note')}));closeModal();await load();toast('Manual time added. DTT totals have been updated.')}catch(error){button.disabled=false;toast(error.message,true)}})}
function deleteManual(id){const m=state.report.manual.find(m=>m.id===id);if(!m)return;confirmModal('Delete this time entry?',`Remove ${num(m.minutes,1)} minutes for ${esc(m.rep)} on ${esc(fmtDate(m.date))}. The reporting totals will update.`,'Delete entry',async()=>{await api('/api/manual/'+encodeURIComponent(id)+'?dataset='+state.dataset,{method:'DELETE'});await load();toast('Manual time entry deleted.')})}
function agentModal(id){if(state.bootstrap.auth.role==='viewer')return toast('An administrator manages team members.',true);const a=id?state.bootstrap.agents.find(a=>a.id===id):{name:'',team:'',active:true};if(!a)return;openModal(id?'Edit team member':'Add team member',id?'Changes apply to this workspace’s roster and reporting filters.':'Create a roster member for manual activity. Outreach records use their separate user identity.',`<form id="agent-form"><div class="form-grid"><div class="field full"><label for="agent-name">Display name</label><input id="agent-name" name="name" value="${esc(a.name)}" maxlength="120" required></div><div class="field full"><label for="agent-team">Team</label><input id="agent-team" name="team" list="team-options" value="${esc(a.team)}" maxlength="120" required><datalist id="team-options">${state.bootstrap.teams.map(t=>`<option value="${esc(t)}">`).join('')}</datalist></div><label class="checkbox-field field full"><span><input name="active" type="checkbox" ${a.active?'checked':''}> Active roster member</span><small>Active agents are included in target calculations.</small></label></div><div class="form-actions"><button class="button" type="button" id="cancel-modal">Cancel</button><button class="button primary" type="submit">Save member</button></div></form>`);$('#agent-form').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.target),button=e.target.querySelector('[type=submit]');button.disabled=true;try{await api(id?'/api/agents/'+encodeURIComponent(id):'/api/agents',payload(id?'PUT':'POST',{dataset:state.dataset,name:f.get('name').trim(),team:f.get('team').trim(),active:f.has('active')}));closeModal();await load(true);toast(id?'Team member updated.':'Team member added. You can now log manual time.')}catch(error){button.disabled=false;toast(error.message,true)}})}
async function saveSettings(e){e.preventDefault();const f=new FormData(e.target),button=e.target.querySelector('[type=submit]');const settings={timezone:f.get('timezone'),dailyTarget:Number(f.get('dailyTarget')),dialCredit:Number(f.get('dialCredit')),directions:f.get('directions')==='both'?['outbound','inbound']:[f.get('directions')],durationMode:f.get('durationMode'),durationField:f.get('durationField').trim(),eligibleStates:f.get('eligibleStates').split(',').map(s=>s.trim().toLowerCase()).filter(Boolean),includeManualCalls:f.has('includeManualCalls')};if(settings.eligibleStates.some(s=>['ringing','in_progress','in-progress','initiated'].includes(s)))return toast('Ringing and in-progress states must remain provisional.',true);button.disabled=true;try{await api('/api/settings',payload('PUT',{dataset:state.dataset,settings}));await load(true);toast('Workspace settings saved and reports recalculated.')}catch(error){button.disabled=false;toast(error.message,true)}}
function callModal(id){const c=state.report.calls.find(c=>c.id===id);if(!c)return;openModal('Call details',`${esc(c.rep)} · ${esc(fmtDate(c.date,{month:'long',day:'numeric',year:'numeric'}))}`,`<div class="call-detail-grid"><div><small>Call state</small>${callStatus(c)}</div><div><small>Call duration</small><p>${c.durationVerified?duration(c.durationSec):'Unverified — excluded'}</p></div><div><small>Reporting date</small><p>${esc(c.date)}</p></div><div><small>Direction</small><p>${esc(c.direction||'Unknown')}</p></div><div><small>Purpose</small><p>${esc(c.purpose||'Not recorded')}</p></div><div><small>Disposition</small><p>${esc(c.disposition||'Not recorded')}</p></div><div><small>Data source</small><p>${esc(c.source==='demo'?'Illustrative sample':c.source)}</p></div><div><small>Call ID</small><p>${esc(c.id)}</p></div><div class="full"><small>Notes</small><p class="call-note-full">${esc(c.note||'No notes recorded.')}</p></div>${c.warnings?.length?`<div class="full notice warning">${icon('info')}<span>${c.warnings.map(w=>esc(typeof w==='string'?w:JSON.stringify(w))).join('<br>')}</span></div>`:''}</div><div class="form-actions"><button class="button" id="cancel-modal">Close</button></div>`)}
function setupModal(){openModal('Outreach setup requirements',preview?'This preview demonstrates the app. Connection requires the full server application.':'An administrator configures these values on the server before authorization.',`<div class="notice warning">${icon('info')}<span>No Outreach credentials are configured in this browser. Credentials belong in the server environment.</span></div><div class="setup-step"><span class="step-num">1</span><div><strong>Register an Outreach OAuth app</strong><p>Use the server callback URL and authorize read access for calls, users, and required webhook operations.</p></div></div><div class="setup-step"><span class="step-num">2</span><div><strong>Configure the server environment</strong><p>Provide the OAuth client ID and secret, redirect URI, explicit scopes, webhook secret, encryption key, and allowed Outreach user IDs.</p></div></div><div class="setup-step"><span class="step-num">3</span><div><strong>Start the app and authorize Outreach</strong><p>The account must be able to read your complete reporting team. Then verify API durations against an Outreach CSV export.</p></div></div><p class="help-text">The full app’s README and environment template contain the deployment and setup instructions. Sample data remains separate from the live workspace.</p><div class="form-actions"><button class="button primary" id="cancel-modal">Got it</button></div>`)}
function parsePreviewCSV(text){const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(field);field=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(v=>v.trim()))rows.push(row);row=[];field=''}else field+=c}if(field||row.length){row.push(field);rows.push(row)}return rows}
function importModal(){if(state.bootstrap.auth.role==='viewer')return toast('An administrator can import call files.',true);let file=null,csv='';openModal('Import Outreach calls',`Upload an Outreach call-list CSV to the ${state.dataset==='demo'?'sample':'live'} workspace. Matching call IDs update existing records.`,`${preview?'<div class="notice warning">'+icon('info')+'<span>You can inspect a file here. Saving imports requires the full app.</span></div>':''}<input id="csv-file" type="file" accept=".csv,text/csv" class="screen-reader"><label class="dropzone" id="dropzone" for="csv-file" tabindex="0">${icon('upload')}<strong>Drop your Outreach CSV here</strong><span class="muted" style="font-size:11px">or click to choose a file</span><small>CSV format · up to 15 MB</small></label><div id="import-file-info"></div><div id="import-preview" class="import-preview"></div><div id="import-result"></div><p class="help-text">Include a unique call ID, agent name, date, and duration. “Duration in Seconds” is preferred. Invalid rows are reported before stored data can be changed.</p><div class="form-actions"><button class="button" id="cancel-modal">Cancel</button><button class="button primary" id="commit-import" disabled>Import calls</button></div>`,true);const accept=async selected=>{if(!selected)return;if(!/\.csv$/i.test(selected.name))return toast('Choose a .csv file exported from Outreach.',true);if(selected.size>15*1024*1024)return toast('Choose a CSV smaller than 15 MB.',true);try{file=selected;csv=await file.text();const rows=parsePreviewCSV(csv);if(rows.length<2)throw Error('The file needs a header and at least one call row.');$('#import-file-info').innerHTML=`<div class="file-selected">${icon('file')}<div><strong>${esc(file.name)}</strong><small>${num(rows.length-1)} data rows · ${num(file.size/1024,1)} KB</small></div></div>`;$('#import-preview').innerHTML=`<p class="help-text" style="margin-bottom:8px">Preview · first ${Math.min(3,rows.length-1)} rows and ${Math.min(5,rows[0].length)} columns. Validation runs on import.</p><div class="table-wrap"><table><thead><tr>${rows[0].slice(0,5).map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.slice(1,4).map(r=>`<tr>${r.slice(0,5).map(c=>`<td><div class="calls-note">${esc(c)}</div></td>`).join('')}</tr>`).join('')}</tbody></table></div>`;$('#commit-import').disabled=false;$('#import-result').innerHTML=''}catch(e){toast(e.message,true)}};$('#csv-file').addEventListener('change',e=>accept(e.target.files[0]));$('#dropzone').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('#csv-file').click()}});for(const evt of['dragenter','dragover'])$('#dropzone').addEventListener(evt,e=>{e.preventDefault();$('#dropzone').classList.add('dragging')});for(const evt of['dragleave','drop'])$('#dropzone').addEventListener(evt,e=>{e.preventDefault();$('#dropzone').classList.remove('dragging');if(evt==='drop')accept(e.dataTransfer.files[0])});$('#commit-import').addEventListener('click',async e=>{if(!file)return;e.target.disabled=true;e.target.textContent='Validating and importing…';try{const result=await api('/api/import',payload('POST',{dataset:state.dataset,csv,filename:file.name}));const errors=result.errors||[],warnings=result.warnings||[];$('#import-result').innerHTML=`<div class="import-result"><strong>${errors.length?'Import contains errors':`${num(result.inserted)} inserted · ${num(result.updated)} updated · ${num(result.skipped)} skipped`}</strong>${errors.length||warnings.length?`<ul>${[...errors,...warnings].slice(0,30).map(w=>`<li>${esc(typeof w==='string'?w:w.message||JSON.stringify(w))}</li>`).join('')}</ul>`:'<p class="help-text">Call records saved. DTT totals have been recalculated.</p>'}</div>`;if(!errors.length){await load(true);e.target.textContent='Imported';toast('Import completed. Your reports are up to date.')}else{e.target.textContent='Import calls';e.target.disabled=false}}catch(error){$('#import-result').innerHTML=`<div class="notice error">${icon('info')}<span>${esc(error.message)}</span></div>${error.details?.errors?.length?`<div class="import-result"><strong>No records were changed.</strong><ul>${error.details.errors.slice(0,30).map(w=>`<li>${esc(typeof w==='string'?w:w.message||JSON.stringify(w))}</li>`).join('')}</ul></div>`:''}`;e.target.disabled=false;e.target.textContent='Import calls'}})}
async function exportReport(){try{let csv;if(preview)csv=await api('/api/export?'+params());else{const res=await fetch('/api/export?'+params());if(!res.ok){const error=await res.json();throw Error(error.error||'Export failed.')}csv=await res.text()}const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`DTT-Pulse-${state.dataset}-${state.start}-to-${state.end}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('DTT report exported.')}catch(e){toast(e.message,true)}}
function showLogin(){openModal('Sign in to DTT Pulse','Enter your workspace password to access reporting data.',`<form id="login-form"><div class="field"><label for="login-password">Workspace password</label><input id="login-password" name="password" type="password" autocomplete="current-password" required></div><div class="form-actions"><button type="submit" class="button primary">Sign in</button></div></form>`);$('#login-form').addEventListener('submit',async e=>{e.preventDefault();const password=new FormData(e.target).get('password');try{await api('/api/login',payload('POST',{password}));closeModal();await load(true)}catch(error){toast(error.message,true)}})}
const hash=location.hash.slice(1);if(nav.some(n=>n[0]===hash))state.page=hash;const oauthReturn=new URLSearchParams(location.search).get('outreach');if(oauthReturn&&!preview){state.dataset='live';state.page='integration';if(oauthReturn==='error')setTimeout(()=>toast('Outreach authorization was not completed. Review the connection status and try again.',true),600)}
load(true);refreshTimer=setInterval(()=>{if(document.visibilityState==='visible'&&state.bootstrap&&!$('#modal-root').children.length&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){if(state.page==='integration')refreshIntegration(true);else load(false,true)}},30000);
window.addEventListener('beforeunload',()=>clearInterval(refreshTimer));
})();
